import { createHash } from 'node:crypto';
import { readdirSync, readFileSync } from 'node:fs';
import { join, resolve } from 'node:path';
import { assertMigrationTargetIsSafe, type EnvSource } from '@kasuwa/config';
import { Client, type QueryConfig } from 'pg';
import { checkNoTransactionFile, hasNoTransactionMarker, NO_TRANSACTION_MARKER } from './migration-sql';
import { readTestAdminUsability, UsableTestAdminError } from './test-admin-guard';

/**
 * Migration runner.
 *
 * Deliberately small and explicit rather than generated by drizzle-kit: RLS
 * policies, FORCE ROW LEVEL SECURITY and grants have no Drizzle representation,
 * and a generated migration would quietly omit them. Hand-written SQL is the
 * source of truth; packages/db/src/schema.ts is the typed mirror.
 *
 * Runs as kasuwa_migrator (DATABASE_MIGRATION_URL), never as kasuwa_app.
 *
 * Properties:
 *   - applied in filename order, one transaction per file — unless the file's
 *     first line is exactly `-- kasuwa:no-transaction` (T-0044, D-L65). A
 *     marked file runs without a transaction, one statement per query, and may
 *     contain only CREATE/DROP INDEX CONCURRENTLY and ALTER TABLE ... VALIDATE
 *     CONSTRAINT (see migration-sql.ts). Every pending marked file is checked
 *     before anything in the run is applied. A marked file that fails part way
 *     is not recorded, so it runs again once fixed; a failed CONCURRENTLY build
 *     leaves an INVALID index to drop first (the create-rls-migration skill
 *     documents the cleanup)
 *   - recorded with a sha256 checksum; editing an applied migration is an error
 *     rather than a silent no-op (expand/migrate/contract means new files, never
 *     edits — see docs/adr/0004 and the migration-reviewer checklist)
 *   - guarded by a session advisory lock so two processes cannot race
 *   - refused, before anything is written (the ledger included), when the
 *     target is not safe to migrate (T-0117, D-L92, D-L94). The environment
 *     checks run before connecting (`assertMigrationTargetIsSafe` in
 *     @kasuwa/config): an invalid environment; an unset NODE_ENV against a
 *     non-local host; and, outside development and test, a PG* fallback or a
 *     repository dev password. Then, outside development and test, the first
 *     query refuses a usable `kasuwa_test_admin` (test-admin-guard.ts). Every
 *     caller (db:migrate, db:reset, tenant:provision, the harness) gets them
 *     because they live here, not in a CLI.
 */

const MIGRATION_TABLE = '_kasuwa_migration';
const ADVISORY_LOCK_KEY = 4_071_020_26; // arbitrary, stable

export interface Migration {
  id: string;
  sql: string;
  checksum: string;
}

export function defaultMigrationsDir(): string {
  return resolve(__dirname, '..', 'migrations');
}

export function loadMigrations(dir: string = defaultMigrationsDir()): Migration[] {
  return readdirSync(dir)
    .filter((name) => name.endsWith('.sql'))
    .sort()
    .map((name) => {
      // Normalise line endings before hashing: the repo is developed on Windows
      // and CI runs on Linux, and git may rewrite them. A checksum that changes
      // with the checkout is worse than no checksum.
      const sql = readFileSync(join(dir, name), 'utf8').replace(/\r\n/g, '\n');
      return {
        id: name.replace(/\.sql$/, ''),
        sql,
        checksum: createHash('sha256').update(sql).digest('hex'),
      };
    });
}

export interface MigrateOptions {
  connectionString: string;
  migrationsDir?: string;
  log?: (message: string) => void;
  /**
   * The raw environment the target guards read, through @kasuwa/config
   * (T-0117). Defaults to `process.env`. NODE_ENV is read from it raw: absent
   * is "unset", which is allowed only against a local host.
   */
  env?: EnvSource;
}

export interface MigrateResult {
  applied: string[];
  alreadyApplied: string[];
}

export async function runMigrations(options: MigrateOptions): Promise<MigrateResult> {
  const log = options.log ?? (() => undefined);
  // Before connecting: a refusal must never depend on reaching the host, and
  // must never be a DNS error that names neither reason.
  const target = assertMigrationTargetIsSafe(options.connectionString, options.env);
  const migrations = loadMigrations(options.migrationsDir ?? defaultMigrationsDir());
  const client = new Client({ connectionString: options.connectionString });
  await client.connect();

  const applied: string[] = [];
  const alreadyApplied: string[] = [];

  try {
    // The first query, before the lock and the ledger: the run writes nothing
    // until the database itself has been judged.
    if (target.enforce) {
      const reasons = await readTestAdminUsability(client);
      if (reasons.length > 0) {
        throw new UsableTestAdminError(
          'Refusing to migrate; nothing was applied',
          target.nodeEnv,
          reasons,
        );
      }
    }
    await client.query(`SELECT pg_advisory_lock($1)`, [ADVISORY_LOCK_KEY]);
    await client.query(`
      CREATE TABLE IF NOT EXISTS ${MIGRATION_TABLE} (
        id          text        PRIMARY KEY,
        checksum    text        NOT NULL,
        applied_at  timestamptz NOT NULL DEFAULT now()
      )
    `);

    const existing = await client.query<{ id: string; checksum: string }>(
      `SELECT id, checksum FROM ${MIGRATION_TABLE}`,
    );
    const byId = new Map(existing.rows.map((row) => [row.id, row.checksum]));

    // Refuse a bad marked file before ANYTHING in this run is applied: without a
    // transaction there is nothing to roll back, so the check has to come first.
    const plans = new Map<string, string[]>();
    for (const migration of migrations) {
      if (byId.has(migration.id) || !hasNoTransactionMarker(migration.sql)) {
        continue;
      }
      const check = checkNoTransactionFile(migration.sql);
      if (check.violations.length > 0) {
        throw new Error(
          `Migration ${migration.id} is marked ${NO_TRANSACTION_MARKER} and was refused; nothing was applied.\n` +
            `A no-transaction migration may contain only CREATE [UNIQUE] INDEX CONCURRENTLY, ` +
            `DROP INDEX CONCURRENTLY and ALTER TABLE ... VALIDATE CONSTRAINT, one action per statement.\n` +
            check.violations.map((violation) => `  - ${violation}`).join('\n'),
        );
      }
      plans.set(migration.id, check.statements);
    }

    for (const migration of migrations) {
      const recorded = byId.get(migration.id);
      if (recorded !== undefined) {
        if (recorded !== migration.checksum) {
          throw new Error(
            `Migration ${migration.id} has already been applied but its contents have changed.\n` +
              `Migrations are append-only: add a new migration instead of editing this one.`,
          );
        }
        alreadyApplied.push(migration.id);
        continue;
      }

      const statements = plans.get(migration.id);
      if (statements !== undefined) {
        log(`applying ${migration.id} (no transaction, ${statements.length} statements)`);
        try {
          for (const statement of statements) {
            // The extended protocol, not the simple one: Postgres refuses more
            // than one command in an extended-protocol query, so if the splitter
            // ever under-split a file the server would reject it rather than
            // run the hidden remainder. (@types/pg lacks `queryMode`; pg has it.)
            const query: QueryConfig & { queryMode: 'extended' } = {
              text: statement,
              queryMode: 'extended',
            };
            await client.query(query);
          }
        } catch (error) {
          // Earlier statements have committed; the file is deliberately NOT
          // recorded, so the next run starts it again.
          throw new Error(
            `Migration ${migration.id} failed: ${(error as Error).message}\n` +
              `It ran without a transaction (${NO_TRANSACTION_MARKER}) and has not been recorded. ` +
              `Statements before the failing one have taken effect. If a CONCURRENTLY build failed, ` +
              `drop the INVALID index it left with DROP INDEX CONCURRENTLY, fix the cause, and run again.`,
            { cause: error },
          );
        }
        await client.query(`INSERT INTO ${MIGRATION_TABLE} (id, checksum) VALUES ($1, $2)`, [
          migration.id,
          migration.checksum,
        ]);
        applied.push(migration.id);
        continue;
      }

      log(`applying ${migration.id}`);
      await client.query('BEGIN');
      try {
        await client.query(migration.sql);
        await client.query(`INSERT INTO ${MIGRATION_TABLE} (id, checksum) VALUES ($1, $2)`, [
          migration.id,
          migration.checksum,
        ]);
        await client.query('COMMIT');
        applied.push(migration.id);
      } catch (error) {
        await client.query('ROLLBACK');
        throw new Error(`Migration ${migration.id} failed: ${(error as Error).message}`, {
          cause: error,
        });
      }
    }
  } finally {
    await client.query(`SELECT pg_advisory_unlock($1)`, [ADVISORY_LOCK_KEY]).catch(() => undefined);
    await client.end();
  }

  return { applied, alreadyApplied };
}
